html:
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set sos = doc.items | map(attribute="sales_order") | select | unique | list -%}
<style>
  .ef-po { font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #1a2030; line-height: 1.5; }
  .ef-po h1 { font-size: 20px; letter-spacing: .14em; margin: 0 0 2px; }
  .ef-po .muted { color: #586273; }
  .ef-po .head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #1a2030; padding-bottom: 10px; margin-bottom: 14px; }
  .ef-po .mono { font-family: Menlo, Consolas, monospace; }
  .ef-po table.meta { width: 100%; border-collapse: collapse; margin-bottom: 14px; }
  .ef-po table.meta td { vertical-align: top; padding: 0 8px 0 0; width: 50%; }
  .ef-po .blk { border: 1px solid #dcdfe6; padding: 9px 11px; min-height: 86px; }
  .ef-po .blk .lbl { font-size: 9.5px; text-transform: uppercase; letter-spacing: .08em; color: #586273; margin-bottom: 4px; }
  .ef-po table.items { width: 100%; border-collapse: collapse; margin: 6px 0 0; }
  .ef-po table.items th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: .06em; border-top: 1px solid #1a2030; border-bottom: 1px solid #1a2030; padding: 6px 8px; }
  .ef-po table.items td { border-bottom: 1px solid #e7e9ee; padding: 6px 8px; vertical-align: top; }
  .ef-po table.items .r { text-align: right; }
  .ef-po table.totals { width: 45%; margin-left: auto; margin-top: 8px; border-collapse: collapse; }
  .ef-po table.totals td { padding: 3px 8px; }
  .ef-po table.totals .r { text-align: right; }
  .ef-po table.totals .grand td { font-weight: bold; font-size: 14px; border-top: 2px solid #1a2030; }
  .ef-po .terms { margin-top: 16px; white-space: pre-wrap; }
  .ef-po .terms .lbl { font-size: 9.5px; text-transform: uppercase; letter-spacing: .08em; color: #586273; margin-bottom: 4px; }
  .ef-po .foot { margin-top: 26px; display: flex; justify-content: space-between; align-items: flex-end; }
  .ef-po .sig { margin-top: 50px; border-top: 1px solid #1a2030; width: 220px; padding-top: 4px; font-size: 10.5px; }
</style>
<div class="ef-po">
  <div class="head">
    <div>
      <h1>PURCHASE ORDER</h1>
      {% if doc.merchant_export_scheme %}<div class="muted">Supply meant for merchant export under notification 41/2017-IGST(R) — concessional 0.1% GST</div>{% endif %}
    </div>
    <div style="text-align:right">
      <div class="mono" style="font-size:14px"><b>{{ doc.name }}</b></div>
      <div class="muted">Date: <span class="mono">{{ frappe.utils.formatdate(doc.transaction_date, "dd MMM yyyy") }}</span></div>
      {% if doc.schedule_date %}<div class="muted">Required by: <span class="mono">{{ frappe.utils.formatdate(doc.schedule_date, "dd MMM yyyy") }}</span></div>{% endif %}
      {% if doc.docstatus == 0 %}<div class="muted"><b>DRAFT</b></div>{% endif %}
    </div>
  </div>

  <table class="meta"><tr>
    <td><div class="blk">
      <div class="lbl">Buyer</div>
      {% set ex = exporter_profile() %}
      <b>{{ ex.company_name }}</b><br>
      {% if ex.address %}<span class="muted" style="white-space:pre-wrap">{{ ex.address | e }}</span><br>{% endif %}
      {% if ex.gstin %}GSTIN: <span class="mono">{{ ex.gstin }}</span><br>{% endif %}
      {% if ex.iec %}IEC: <span class="mono">{{ ex.iec }}</span>{% endif %}
    </div></td>
    <td><div class="blk">
      <div class="lbl">Supplier</div>
      {% set sup_addr = party_address("Supplier", doc.supplier) %}
      <b>{{ doc.supplier_name }}</b><br>
      {% if sup_addr %}<span class="muted" style="white-space:pre-wrap">{{ sup_addr | e }}</span><br>{% endif %}
      {% if doc.get("supplier_gstin") %}GSTIN: <span class="mono">{{ doc.supplier_gstin }}</span>{% endif %}
    </div></td>
  </tr></table>

  {% if sos %}<div class="muted" style="margin-bottom:6px">Against sales order{{ "s" if sos | length > 1 else "" }}: <span class="mono">{{ sos | join(", ") }}</span> — goods to be delivered directly to the port of shipment (drop ship)</div>{% endif %}

  <table class="items">
    <thead><tr><th style="width:26px">#</th><th>Description</th><th>HSN</th><th class="r">Qty</th><th class="r">Rate</th><th class="r">Amount ({{ doc.currency }})</th></tr></thead>
    <tbody>
    {% for row in doc.items %}
      <tr>
        <td class="mono">{{ loop.index }}</td>
        <td><b>{{ row.item_name }}</b>{% if row.item_code != row.item_name %}<br><span class="muted mono" style="font-size:10px">{{ row.item_code }}</span>{% endif %}{% if row.sales_order %}<br><span class="muted" style="font-size:10px">for {{ row.sales_order }}</span>{% endif %}</td>
        <td class="mono">{{ row.get("gst_hsn_code") or "" }}</td>
        <td class="r mono">{{ frappe.utils.flt(row.qty) }} {{ row.uom or "" }}</td>
        <td class="r mono">{{ frappe.utils.fmt_money(row.rate, currency=doc.currency) }}</td>
        <td class="r mono">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>

  <table class="totals">
    <tr><td class="muted">Net total</td><td class="r mono">{{ frappe.utils.fmt_money(doc.net_total, currency=doc.currency) }}</td></tr>
    {% for tax in doc.taxes %}
    <tr><td class="muted">{{ tax.description }}{% if tax.rate %} @ {{ frappe.utils.flt(tax.rate) }}%{% endif %}</td><td class="r mono">{{ frappe.utils.fmt_money(tax.base_tax_amount_after_discount_amount or tax.tax_amount, currency=doc.currency) }}</td></tr>
    {% endfor %}
    <tr class="grand"><td>Grand total</td><td class="r mono">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td></tr>
    <tr><td colspan="2" class="muted" style="font-size:10.5px">{{ frappe.utils.money_in_words(doc.grand_total, doc.currency) }}</td></tr>
  </table>

  {% if doc.terms %}
  <div class="terms">
    <div class="lbl">Terms &amp; conditions{% if doc.tc_name %} · {{ doc.tc_name }}{% endif %}</div>{{ doc.terms | striptags }}
  </div>
  {% endif %}

  <div class="foot">
    <div class="muted" style="font-size:10.5px">This purchase order is system generated by ExportFlow.</div>
    <div>
      <div class="muted" style="font-size:10.5px">For {{ company.company_name }}</div>
      <div class="sig">Authorised signatory</div>
    </div>
  </div>
</div>
